# coding: utf-8
from lesson_authoring import entry as E
B=[['希腊磁石名称 → 拉丁 magnes、magnet- → 英语 magnet','磁石 → 磁铁']]
W=[
E('magnetize','/ˈmæɡnɪtaɪz/','使磁化；使具有磁性','原来吸不起小螺丝的工具，经过磁化后能把它带起来。','magnet + -ize，使具有磁铁的性质。',B+[['英语 magnet + -ize → magnetize','磁铁 → 使具有磁性']],'magnetize a needle 是让针获得磁性。这个词说的是改变材料的磁性状态，不是把一块磁铁粘上去；日常工具也可能有 magnetized tip 磁化的尖端。','magnetize a needle；magnetize a material；a magnetized screwdriver。','magnetic 描述已有的性质；magnetize 表示使性质发生变化。',('The technician used a device to magnetize the screwdriver.','技术员用一个装置把螺丝刀磁化。'),('The experiment showed how a steel needle could be magnetized.','实验展示了一根钢针如何获得磁性。')),
E('magnetization','英 /ˌmæɡnɪtaɪˈzeɪʃən/；美 /ˌmæɡnɪtəˈzeɪʃən/','磁化；磁化状态或磁化强度','不仅问“有没有磁性”，还可以研究磁化怎样发生、达到什么状态。','magnetize + -ation，表示磁化过程或结果；物理中也作专门量名。',B+[['英语 magnetize → magnetization','使磁化 → 磁化过程及状态']],'日常学习先记“使材料获得或改变磁性的过程”。物理文章里的 magnetization 还可指磁化强度这一量，不能在所有句子里都翻成一次操作。','the magnetization of a material；residual magnetization；measure magnetization。','magnetism 泛指磁性及相关现象；magnetization 更具体地指磁化或材料的磁化量。',('The experiment measured the sample’s magnetization.','实验测量了样品的磁化强度。'),('Some magnetization remained after the external field was removed.','外部磁场撤去后，材料仍保留了一部分磁化状态。')),
E('magnetometer','英 /ˌmæɡnɪˈtɒmɪtə/；美 /ˌmæɡnɪˈtɑːmɪtər/','磁力计；磁强计','把看不见的磁场变成能读出来的数据。','magneto- 磁 + -meter 测量仪器。',B+[['magneto- + -meter → magnetometer','磁 + 测量工具 → 测磁场的仪器']],'探测器可以带着 magnetometer 测量行星周围的磁场。不同仪器测磁场大小、方向或某个分量，词义核心是测磁场，而不是量磁铁的尺寸或重量。','a spacecraft magnetometer；magnetometer readings；a sensitive magnetometer。','thermometer 测温度；magnetometer 测磁场。-meter 给出“测量工具”，前面的词根告诉你测什么。',('The spacecraft carries a magnetometer to study the planet’s magnetic field.','航天器携带磁力计研究这颗行星的磁场。'),('A nearby metal object affected the magnetometer readings.','附近一件金属物体影响了磁力计的读数。'),sources=['https://en.wiktionary.org/wiki/magnetometer','https://science.nasa.gov/mission/cassini/spacecraft/cassini-orbiter/magnetometer/']),
E('magnetite','/ˈmæɡnɪtaɪt/','磁铁矿','名字直接提醒你：这是一种与磁性密切相关的矿物。','magnet + 矿物名后缀 -ite，参照德语 Magnetit。',B+[['德语 Magnetit／英语 magnet + -ite → magnetite','磁铁 + 矿物名称 → 磁铁矿']],'magnetite 是一种铁氧化物矿物，化学式 Fe₃O₄。天然磁化的磁铁矿可形成 lodestone 天然磁石。矿物名称讲的是成分和晶体类别，magnet 则是磁铁这一类物体。','magnetite ore；magnetite crystals；a sample of magnetite。','magnetite 是特定矿物，magnet 可以由不同材料制成。别把所有磁铁都叫 magnetite。',('The sample contains small crystals of magnetite.','这个样品含有细小的磁铁矿晶体。'),('Students compared magnetite with other iron minerals.','学生比较了磁铁矿和其他含铁矿物。'),sources=['https://en.wiktionary.org/wiki/magnetite','https://www.etymonline.com/word/magnetite','https://arxiv.org/abs/1004.2231'])]
